python
def facingCardsProofStrip(readings):
    a=readings
    out=[]
    l,r=0,len(a)-1
    while l<=r:
        out.append(a[l] if l==r else a[l]+a[r])
        l+=1
        r-=1
    return out


java
class Solution {
  public int[] facingCardsProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int l=0,r=a.length-1;l<=r;l++,r--)out.add(l==r?a[l]:a[l]+a[r]);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
